import{_ as l,o as t,c as a,a5 as i}from"./chunks/framework.BPFk9-tb.js";const h=JSON.parse('{"title":"写作课作业-069","description":"","frontmatter":{"date":"2020-09-26T21:03:56","title":"写作课作业-069","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"思考","slug":"思考","link":"#思考","children":[]}],"relativePath":"posts/homework/069.md","filePath":"posts/homework/069.md"}'),o={name:"posts/homework/069.md"};function r(s,e,n,p,c,_){return t(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p>9.26 写作作业：读《微信互联网平民创业》之《2. 你应该把微信当作什么》，读书笔记的模板（可以在此基础上，资源发挥）：</p><ol><li>总结书中知识要点：</li><li>我对知识点的思考：</li><li>书中精彩的例子，可以用在其他什么地方：</li><li>书中用了排比、递进、转折了吗？</li><li>哪些知识点可以运用到自己学习、生活和工作中。</li></ol></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li><p>微信已然吞噬了整个世界，整个世界都是由经济构成的，微信是一个经济世界......</p></li><li><p>做个商人，做好一个商人，做一个好商人。</p></li><li><p>我是想说，脑子要清楚一点，心态要健康一点：我们就应该把微信理解为一个商业世界; 我们应该在这个商业世界里做个好商人......换个更为简单直接的说法：我们是平⺠，微信是我们的赚钱工具。</p></li></ul><h2 id="思考" tabindex="-1">思考 <a class="header-anchor" href="#思考" aria-label="Permalink to &quot;思考&quot;">​</a></h2><p>对于解释“我们所生存的世界，它的构成究竟是怎样的呢?”，我想到的是笑来老师讲的，概念和概念的关系。从世界由政治、经济、娱乐、教育、情感等概念构成，到这些基础概与经济的关系，推出一切都是经济的时候，“经济基础决定上层建筑”曾经一直认为是句口号的话，就像看得见了一样。</p><p>我们开发经常会抱怨某个中间件不好用，但是后面回头看文档的时候其实是说明文档没有读明白，使用方式不对。</p>',6)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
